// Lookup finds a setting by name.
func Lookup(name string) (Setting, bool) {
	for _, s := range Catalogue {
		if s.Name == name {
			return s, true
		}
	}
	return Setting{}, false
}

// Names lists every setting name (deploy scripts and Terraform must match; see the tests).
func Names() []string {
	out := make([]string, len(Catalogue))
	for i, s := range Catalogue {
		out[i] = s.Name
	}
	return out
}

// ErrUnknown: not a setting the console manages.
var ErrUnknown = errors.New("unknown setting")

// Invalid is why a value was refused, as a sentence the lead reads on the page.
type Invalid string

func (e Invalid) Error() string { return string(e) }

// Validate trims the value and checks it. The error is a sentence a lead can act on.
func Validate(name, value string) (string, error) {
	s, ok := Lookup(name)
	if !ok {
		return "", ErrUnknown
	}
	v := strings.TrimSpace(value)
	if v == "" {
		return "", Invalid("Enter a value.")
	}
	for _, r := range v {
		if unicode.IsControl(r) {
			return "", Invalid("The value has a line break or a hidden character. Paste it again as one line.")
		}
	}
	if err := s.check(v); err != nil {
		return "", err
	}
	return v, nil
}

// Status is what the console may know about a setting: never its value.
type Status struct {
	Set     bool      `json:"set"`
	Updated time.Time `json:"updated,omitempty"`
}

// Store keeps the values.
type Store interface {
	// Status reports, per name, whether a value is set and when it was last changed.
	Status(ctx context.Context, names []string) (map[string]Status, error)
	// Set stores a new value (a new version; earlier versions stay in Secret Manager's history).
	Set(ctx context.Context, name, value string) error
	// Apply asks the server to restart the services with the stored values.
	Apply(ctx context.Context) error
}

// --- checks ---

func text(min, max int) func(string) error {
	return func(v string) error {
		if len(v) < min {
			return Invalid(fmt.Sprintf("That looks too short: it should be at least %d characters.", min))
		}
		if len(v) > max {
			return Invalid(fmt.Sprintf("That's longer than expected (over %d characters).", max))
		}
		return nil
	}
}

func prefixed(prefixes ...string) func(string) error {
	return func(v string) error {
		for _, p := range prefixes {
			if strings.HasPrefix(v, p) && len(v) > len(p)+4 && !strings.ContainsAny(v, " \t") {
				return nil
			}
		}
		return Invalid(fmt.Sprintf("It should start with %s.", strings.Join(prefixes, " or ")))
	}
}

func httpsURL(v string) error {
	u, err := url.Parse(v)
	if err != nil || u.Scheme != "https" || u.Host == "" || u.User != nil {
		return Invalid("Enter the full address, starting with https://")
	}
	return nil
}

func hostname(v string) error {
	if strings.ContainsAny(v, " /:@") || !strings.Contains(v, ".") || len(v) > 253 {
		return Invalid("Enter just the server name, e.g. smtp.hostinger.com")
	}
	return nil
}

func port(v string) error {
	n, err := strconv.Atoi(v)
	if err != nil || (n != 465 && n != 587) {
		return Invalid("Use 465 (or 587).")
	}
	return nil
}

func email(v string) error {
	a, err := mail.ParseAddress(v)
	if err != nil || a.Address != v {
		return Invalid("Enter an email address, e.g. hello@yourdomain")
	}
	return nil
}

func sender(v string) error {
	a, err := mail.ParseAddress(v)
	if err != nil || a.Name == "" {
		return Invalid(`Enter a name and an address, e.g. Member services <hello@yourdomain>`)
	}
	if strings.Contains(strings.ToLower(a.Name), "tryst") {
		return Invalid("Use a neutral name: the sender must not say TRYST (members' inboxes may be seen by others).")
	}
	return nil
}

func slug(v string) error {
	for _, r := range v {
		if !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-' || r == '_') {
			return Invalid("Use lower-case letters, digits and dashes only, e.g. yoti")
		}
	}
	return nil
}

func certRecords(v string) error {
	ps, err := assurance.ParseRecords(v)
	if err != nil {
		return Invalid(fmt.Sprintf("The certificate list isn't valid: %v.", err))
	}
	if len(ps) == 0 {
		return Invalid("Add at least one provider and its certificates.")
	}
	return nil
}
